/* 滚动条美化 - iPhone风格 */
.story-list-container::-webkit-scrollbar,
.detail-content::-webkit-scrollbar {
  width: 4px;
}

.story-list-container::-webkit-scrollbar-track,
.detail-content::-webkit-scrollbar-track {
  background: transparent;
}

.story-list-container::-webkit-scrollbar-thumb,
.detail-content::-webkit-scrollbar-thumb {
  background: rgba(120, 120, 128, 0.3);
  border-radius: 2px;
}

.story-list-container::-webkit-scrollbar-thumb:hover,
.detail-content::-webkit-scrollbar-thumb:hover {
  background: rgba(120, 120, 128, 0.5);
}

/* 动画增强 */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 弹出面板动画 - 从下方向上滑入 */
@keyframes popupSlideUp {
  from {
    opacity: 0;
    transform: translateY(20px) scaleY(0.8);
    max-height: 0;
  }
  to {
    opacity: 1;
    transform: translateY(0) scaleY(1);
    max-height: calc(100vh - 80px);
  }
}

/* 弹出面板隐藏动画 - 向下滑出 */
@keyframes popupSlideDown {
  from {
    opacity: 1;
    transform: translateY(0) scaleY(1);
    max-height: calc(100vh - 80px);
  }
  to {
    opacity: 0;
    transform: translateY(20px) scaleY(0.8);
    max-height: 0;
  }
}

.main-interface {
  animation: fadeInUp 0.5s ease-out;
}

/* 无障碍支持 */
.control-btn:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.story-item:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

/* 剧情详情样式 */
.story-info-section {
  margin-bottom: 16px;
}

/* 返回列表按钮样式 */
.back-to-list-btn {
  width: 32px;
  height: 32px;
  border: none;
  background: rgba(120, 120, 128, 0.2);
  border-radius: 16px;
  color: var(--text-primary);
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  margin-right: 8px;
}

.back-to-list-btn:hover {
  background: rgba(120, 120, 128, 0.3);
  transform: scale(1.05);
}

/* 压缩的详情项样式 */
.detail-item.compact {
  margin-bottom: 8px;
}

.detail-item.compact label {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 2px;
  display: block;
}

.detail-item.compact div {
  font-size: 14px;
  color: var(--text-primary);
  line-height: 1.3;
}

.steps-section {
  margin-top: 16px;
}

.steps-title {
  margin: 0 0 16px 0;
  font-size: 18px;
  font-weight: 600;
  color: var(--text-primary);
}

.steps-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* 步骤项样式 */
.step-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.7);
  border-radius: var(--border-radius-small);
  border: 1px solid var(--border-color);
  transition: var(--transition);
}

.step-item.executed {
  background: rgba(52, 199, 89, 0.1);
  border-color: var(--success-color);
}

.step-item.pending {
  background: rgba(255, 149, 0, 0.1);
  border-color: var(--warning-color);
}

.step-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.step-header-line {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.step-id {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
}

.step-characters-inline {
  font-size: 12px;
  color: var(--primary-color);
  font-weight: 500;
  flex: 1;
  min-width: 0;
}

.step-characters-inline .label {
  color: var(--text-secondary);
  font-weight: 500;
}

.step-event-line {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.3;
}

.step-event-line .label {
  color: var(--text-secondary);
  font-weight: 500;
}

.step-actions {
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.step-execute-btn {
  padding: 8px 16px;
  border: none;
  border-radius: var(--border-radius-small);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  gap: 6px;
}

.step-execute-btn.pending {
  background: var(--primary-color);
  color: white;
}

.step-execute-btn.pending:hover {
  background: #0056d3;
  transform: translateY(-1px);
}

.step-execute-btn.executed {
  background: var(--success-color);
  color: white;
}

.step-execute-btn.executed:hover {
  background: #28a745;
  transform: translateY(-1px);
}

.step-execute-btn:active {
  transform: translateY(0);
}

