  /**
   * 显示/隐藏剧情列表
   */
  function toggleStoryList() {
    const $section = $('#storyListSection');

    if ($section.is(':visible')) {
      hideStoryList();
    } else {
      showStoryList();
    }
  }

  /**
   * 显示剧情列表
   */
  function showStoryList() {
    const $section = $('#storyListSection');
    const $listContainer = $('#storyListContainer');

    // 清空并重新构建列表
    $listContainer.empty();

    stories.forEach((story, index) => {
      // 计算已执行步骤数
      const executedStepsCount = story.steps.filter(step => step.isExecute).length;
      const totalStepsCount = story.steps.length;
      const isCurrentPlot = story.id === currentPlot;

      const $item = $(`
        <div class="story-item ${isCurrentPlot ? 'current' : ''}" data-index="${index}">
          <div class="story-item-content">
            <div class="story-item-title">${story.title}</div>
            <div class="story-item-location">📍 ${story.location || '未指定'}</div>
            <div class="story-item-progress">${executedStepsCount}/${totalStepsCount} 步骤</div>
          </div>
        </div>
      `);
      $listContainer.append($item);
    });

    // 立即显示，无动画
    $section.show().addClass('show').css({
      transition: 'none',
      transform: 'translateY(0) scaleY(1)',
      opacity: '1',
    });

    // 自动滚动到当前剧情（currentPlot.uniqueID）
    setTimeout(() => {
      const currentPlotIndex = stories.findIndex(story => story.id === currentPlot);
      if (currentPlotIndex !== -1) {
        const $currentItem = $listContainer.find(`.story-item[data-index="${currentPlotIndex}"]`);
        if ($currentItem.length > 0) {
          // 使用 scrollIntoView 滚动到当前剧情
          $currentItem[0].scrollIntoView({
            behavior: 'smooth',
            block: 'center',
          });
          console.log('✅ 自动滚动到当前剧情：', stories[currentPlotIndex].title);
        }
      }
    }, 350); // 等待弹出动画完成后再滚动

    // 展开插件
    if (typeof window.expandPlugin === 'function') {
      window.expandPlugin();
    }

    // 额外通知高度变化（确保iframe正确调整）
    setTimeout(() => {
      if (typeof window.notifyParentHeightChange === 'function') {
        window.notifyParentHeightChange();
      }
    }, 100);

    // 再次通知（防止初次计算不准确）
    setTimeout(() => {
      if (typeof window.notifyParentHeightChange === 'function') {
        window.notifyParentHeightChange();
      }
    }, 400);
  }

  /**
   * 隐藏剧情列表
   */
  function hideStoryList() {
    const $section = $('#storyListSection');
    $section.removeClass('show');
    setTimeout(() => {
      $section.hide();
    }, 300);

    // 收缩插件
    if (typeof window.collapsePlugin === 'function') {
      window.collapsePlugin();
    }
  }

  /**
   * 切换排序顺序
   */
  function toggleSortOrder() {
    sortOrder = sortOrder === 'asc' ? 'desc' : 'asc';
    sortStories();
    updateSortButton();
    showStoryList(); // 重新显示列表
    showFeedback(`已按序号${sortOrder === 'asc' ? '正向' : '反向'}排序`);
  }

  /**
   * 对剧情进行排序
   */
  function sortStories() {
    const currentStoryId = stories[currentStoryIndex]?.id;

    stories.sort((a, b) => {
      if (sortOrder === 'asc') {
        return a.id - b.id;
      } else {
        return b.id - a.id;
      }
    });

    // 重新找到当前剧情的索引
    if (currentStoryId) {
      const newIndex = stories.findIndex(story => story.id === currentStoryId);
      if (newIndex !== -1) {
        currentStoryIndex = newIndex;
      }
    }

    updateDisplay();
  }

  /**
   * 更新排序按钮显示
   */
  function updateSortButton() {
    const $sortBtn = $('#sortBtn');
    $sortBtn.removeClass('asc desc').addClass(sortOrder);

    if (sortOrder === 'asc') {
      $sortBtn.find('.btn-icon').text('↑');
      $sortBtn.attr('title', '当前正向排序，点击反向排序');
    } else {
      $sortBtn.find('.btn-icon').text('↓');
      $sortBtn.attr('title', '当前反向排序，点击正向排序');
    }
  }

  /**
   * 获取当前步骤信息
   */
  function getCurrentStepInfo(story, stepId) {
    if (!story || !story.steps) return null;
    // 使用 == 进行比较，允许字符串和数字的比较
    return story.steps.find(step => step.stepId == stepId) || story.steps[0];
  }

  /**
   * 更新推进剧情显示
   */
  function updateProgressDisplay(currentStory) {
    const $progressDisplay = $('#storyProgress');

    if (!currentStory || !currentStory.steps) {
      $progressDisplay.hide();
      return;
    }

    // 查找当前剧情的下一个未执行步骤
    const nextStep = getNextStep(currentStory);

    if (nextStep) {
      // 当前剧情还有未执行步骤
      const progressText = `推进剧情: 步骤 ${nextStep.stepId} - ${nextStep.event || '未指定'}`;
      $progressDisplay.text(progressText).show();
    } else {
      // 当前剧情已完成，查找下一个剧情的第一个步骤
      const nextStoryStep = getNextStoryFirstStep();
      if (nextStoryStep) {
        const progressText = `推进剧情: 下一剧情 - ${nextStoryStep.event || '未指定'}`;
        $progressDisplay.text(progressText).show();
      } else {
        // 已经是最后一个剧情且已完成
        $progressDisplay.text('推进剧情: 所有剧情已完成').show();
      }
    }
  }

  /**
   * 获取当前剧情的下一个未执行步骤
   */
  function getNextStep(story) {
    if (!story || !story.steps) return null;

    // 查找第一个未执行的步骤
    return story.steps.find(step => !step.isExecute);
  }

  /**
   * 获取下一个剧情的第一个步骤
   */
  function getNextStoryFirstStep() {
    if (currentStoryIndex >= stories.length - 1) return null;

    const nextStory = stories[currentStoryIndex + 1];
    if (!nextStory || !nextStory.steps || nextStory.steps.length === 0) return null;

    return nextStory.steps[0];
  }

  /**
   * 处理返回上步操作
   */
  async function handlePreviousStep() {
    const currentStory = stories[currentStoryIndex];
    if (!currentStory) {
      showFeedback('没有可用的剧情');
      return;
    }

    // 使用当前步骤ID进行计算（stepId - 1）
    const currentStepIdNum = parseInt(currentStepId);

    if (currentStepIdNum > 1) {
      // 当前步骤ID大于1，返回到上一个步骤
      const previousStepId = (currentStepIdNum - 1).toString();

      // 检查上一个步骤是否存在（使用 == 允许字符串和数字比较）
      const prevStep = currentStory.steps.find(step => step.stepId == previousStepId);
      if (prevStep) {
        currentStepId = previousStepId;
        currentStory.currentStepId = previousStepId;

        // 在生产环境中保存状态
        await saveCurrentPlotToWorldbook();

        updateDisplay();
        showFeedback(`已返回到步骤 ${previousStepId}`);
      } else {
        showFeedback(`步骤 ${previousStepId} 不存在`);
      }
    } else {
      // 当前步骤ID为1，返回到上一个剧情的最后一个步骤
      if (currentStoryIndex > 0) {
        currentStoryIndex--;
        const prevStory = stories[currentStoryIndex];
        if (prevStory.steps && prevStory.steps.length > 0) {
          // 找到上一个剧情的最后一个步骤
          const lastStep = prevStory.steps[prevStory.steps.length - 1];
          currentPlot = prevStory.id;
          currentStepId = lastStep.stepId;
          prevStory.currentStepId = lastStep.stepId;

          // 在生产环境中保存状态
          await saveCurrentPlotToWorldbook();

          updateDisplay();
          showFeedback(`已返回到上一个剧情的最后步骤：${lastStep.stepId}`);
        } else {
          showFeedback('上一个剧情没有可用步骤');
        }
      } else {
        showFeedback('已经是第一个剧情的第一个步骤了');
      }
    }
  }

  /**
   * 处理继续剧情操作
   */
  async function handleNextStep() {
    const currentStory = stories[currentStoryIndex];
    if (!currentStory) {
      showFeedback('没有可用的剧情');
      return;
    }

    // 查找当前剧情的下一个未执行步骤
    const nextStep = getNextStep(currentStory);

    if (nextStep) {
      // 当前剧情还有未执行步骤，执行该步骤
      executeStep(nextStep.stepId);
    } else {
      // 当前剧情已完成，前进到下一个剧情的第一个步骤
      if (currentStoryIndex < stories.length - 1) {
        currentStoryIndex++;
        const nextStory = stories[currentStoryIndex];
        if (nextStory.steps && nextStory.steps.length > 0) {
          // 更新当前剧情和步骤ID
          currentPlot = nextStory.id;
          currentStepId = nextStory.steps[0].stepId;
          nextStory.currentStepId = nextStory.steps[0].stepId;

          // 在生产环境中保存状态
          await saveCurrentPlotToWorldbook();

          updateDisplay();
          hideStoryList(); // 关闭剧情列表
          // 不再自动打开详情，只显示反馈
          showFeedback(`已前进到下一个剧情：${nextStory.title}`);
        } else {
          showFeedback('下一个剧情没有可用步骤');
        }
      } else {
        showFeedback('已经是最后一个剧情了');
      }
    }
  }

  /**
   * 更新当前剧情ID - 仅用于导航时同步显示
   * 注意：这里只是同步显示，不改变数据源中的currentPlot
   */
  function updateCurrentPlot() {
    // 这个函数仅用于导航时的显示同步，不应该修改原始的currentPlot
    // 原始的currentPlot来自数据源，应该保持不变直到真正执行剧情
    console.log(
      '导航显示更新：当前显示剧情ID',
      stories[currentStoryIndex]?.id,
      '数据源currentPlot:',
      currentPlot,
      'stepId:',
      currentStepId,
    );
  }

  /**
   * 回到数据源中的当前剧情
   */
  function backToCurrentPlot() {
    if (!stories || stories.length === 0) {
      showFeedback('没有可用的剧情数据');
      return;
    }

    if (currentPlot === '0' || currentPlot === '') {
      showFeedback('数据源中未设置当前剧情');
      return;
    }

    // 查找数据源中currentPlot对应的剧情索引
    const targetIndex = stories.findIndex(story => story.id === currentPlot);

    if (targetIndex === -1) {
      showFeedback(`找不到剧情ID ${currentPlot}，请检查数据源`);
      console.error(
        '找不到当前剧情：',
        currentPlot,
        '可用剧情：',
        stories.map(s => s.id),
      );
      return;
    }

    // 如果已经在当前剧情，提示用户
    if (targetIndex === currentStoryIndex) {
      showFeedback('已经在当前剧情了');
      return;
    }

    // 切换到目标剧情
    const previousIndex = currentStoryIndex;
    currentStoryIndex = targetIndex;
    updateDisplay();

    // 关闭可能打开的面板
    hideStoryList();
    hideStoryDetail();
    hideSettingsPanel();

    // 提供详细的反馈信息
    const currentStory = stories[currentStoryIndex];
    showFeedback(`✅ 已回到数据源当前剧情：${currentStory.title}`);
    console.log(`回到当前剧情：从索引 ${previousIndex} 跳转到索引 ${currentStoryIndex}，剧情ID: ${currentPlot}`);
  }

  /**
   * 显示剧情详情页面
   */
  function showStoryDetail() {
    try {
      if (!stories[currentStoryIndex]) {
        console.warn('showStoryDetail: 无效的currentStoryIndex:', currentStoryIndex);
        return;
      }

      const story = stories[currentStoryIndex];
      if (!story) {
        console.warn('showStoryDetail: 无效的故事对象');
        return;
      }

      // 更新剧情基本信息
      $('#detailTitle').text(story.title || '未指定');
      $('#detailLocation').text(story.location || '未指定');
      $('#detailCoreConflict').text(story.description || '未指定');

      // 检查并处理步骤数组
      if (!story.steps || !Array.isArray(story.steps)) {
        console.warn('showStoryDetail: 故事没有有效的步骤数组:', story);
        $('#stepsList').html('<div class="no-steps">此剧情暂无可用步骤</div>');
      } else {
        // 生成步骤列表
        const stepsHtml = story.steps
          .map(step => {
            if (!step) {
              console.warn('showStoryDetail: 发现无效的步骤对象');
              return '';
            }

            const isExecuted = step.isExecute;
            const statusClass = isExecuted ? 'executed' : 'pending';
            const buttonText = isExecuted ? '重新执行' : '执行';
            const buttonIcon = isExecuted ? '🔄' : '▶';

            return `
            <div class="step-item ${statusClass}">
              <div class="step-content">
                <div class="step-header-line">
                  <div class="step-id">步骤 ${step.stepId || '未知'}</div>
                  <div class="step-characters-inline">
                    <span class="label">人物:</span> ${step.characters || '未指定'}
                  </div>
                </div>
                <div class="step-event-line">
                  <span class="label">事件:</span> ${step.event || '未指定'}
                </div>
              </div>
              <div class="step-actions">
                <button class="step-execute-btn ${statusClass}" data-step-id="${step.stepId || ''}">
                  <span class="btn-icon">${buttonIcon}</span>
                  <span>${buttonText}</span>
                </button>
              </div>
            </div>
          `;
          })
          .filter(html => html !== '')
          .join('');

        $('#stepsList').html(stepsHtml);
      }

      // 立即显示，无动画
      const $section = $('#storyDetailSection');
      $section.show().addClass('show').css({
        transition: 'none',
        transform: 'translateY(0) scaleY(1)',
        opacity: '1',
      });

      // 展开插件
      if (typeof window.expandPlugin === 'function') {
        window.expandPlugin();
      }

      // 额外通知高度变化（确保iframe正确调整）
      setTimeout(() => {
        if (typeof window.notifyParentHeightChange === 'function') {
          window.notifyParentHeightChange();
        }
      }, 100);

      // 再次通知（防止初次计算不准确）
      setTimeout(() => {
        if (typeof window.notifyParentHeightChange === 'function') {
          window.notifyParentHeightChange();
        }
      }, 400);
    } catch (error) {
      console.error('showStoryDetail 错误:', error);
      showFeedback(`显示剧情详情时出错: ${error.message}`);
    }
  }

  /**
   * 隐藏剧情详情
   */
  function hideStoryDetail() {
    const $section = $('#storyDetailSection');
    $section.removeClass('show');
    setTimeout(() => {
      $section.hide();
    }, 300);

    // 收缩插件
    if (typeof window.collapsePlugin === 'function') {
      window.collapsePlugin();
    }
  }

  /**
   * 显示/隐藏设置面板
   */
  function toggleSettingsPanel() {
    const $section = $('#settingsSection');

    if ($section.hasClass('show')) {
      hideSettingsPanel();
    } else {
      showSettingsPanel();
    }
  }

  /**
   * 显示设置面板
   */
  function showSettingsPanel() {
    // 同步设置状态到界面
    syncSettingsToUI();

    const $section = $('#settingsSection');
    $section.show().addClass('show').css({
      transition: 'none',
      transform: 'translateY(0) scaleY(1)',
      opacity: '1',
    });

    // 展开插件
    if (typeof window.expandPlugin === 'function') {
      window.expandPlugin();
    }
  }

  /**
   * 同步设置状态到界面
   */
  function syncSettingsToUI() {
    // 同步主题设置
    $('#themeSelect').val(themeSettings.currentTheme);

    // 同步执行策略设置
    $('#executionStrategySelect').val(executionStrategy.mode);
  }

  /**
   * 隐藏设置面板
   */
  function hideSettingsPanel() {
    const $section = $('#settingsSection');
    $section.removeClass('show');
    setTimeout(() => {
      $section.hide();
    }, 300);

    // 收缩插件
    if (typeof window.collapsePlugin === 'function') {
      window.collapsePlugin();
    }
  }

  /**
   * 执行指定步骤
   */
  async function executeStep(stepId) {
    if (!stories[currentStoryIndex]) {
      showFeedback('没有可用的剧情');
      return;
    }

    const currentStory = stories[currentStoryIndex];
    // 使用 == 进行比较，允许字符串和数字的比较
    const targetStep = currentStory.steps.find(step => step.stepId == stepId);

    if (!targetStep) {
      showFeedback(`步骤 ${stepId} 不存在`);
      console.error('找不到步骤:', {
        stepId,
        stepIdType: typeof stepId,
        availableSteps: currentStory.steps.map(s => ({ id: s.stepId, type: typeof s.stepId })),
      });
      return;
    }

    try {
      // 1. 更新本地的currentPlot和stepId
      currentPlot = currentStory.id;
      currentStepId = stepId;

      // 2. 先将 storyTitle 文本设置为执行的 name
      $('#storyTitle').text(currentStory.title);

      // 3. 构建要发送的步骤对象
      const stepObject = buildStepObject(currentStory, targetStep);

      // 4. 拼装要发送的text
      const textToSend = formatStepObjectAsText(stepObject);

      console.log('textToSend======== ', textToSend);

      // 5. 根据执行策略选择调用方式
      if (executionStrategy.mode === 'copy') {
        // 复制到酒馆对话框
        const success = copyToTavernTextarea(textToSend);
        if (success) {
          showFeedback('📋 已复制到酒馆对话框，请手动发送');
        }
      } else {
        // 直接执行（默认）
        triggerQuickReply(textToSend);
      }

      // 6. 标记当前步骤为已执行
      targetStep.isExecute = true;

      // 7. 更新剧情的执行状态
      currentStory.isExecuted = currentStory.steps.some(step => step.isExecute);

      // 8. 在生产环境中保存状态到世界书
      await saveCurrentPlotToWorldbook();

      // 9. 更新剧情执行状态到世界书
      await updateStoryExecutionStatus(currentStory);

      // 10. 更新显示
      updateDisplay();
      // 移除自动打开详情，让用户手动控制

      // 11. 显示执行反馈
      showFeedback(`✅ 已执行步骤 ${stepId}："${currentStory.title}"`);

      console.log('✅ 步骤执行完成：', {
        story: currentStory.title,
        stepId: stepId,
        stepObject: stepObject,
        textSent: textToSend,
      });
    } catch (error) {
      console.error('执行步骤时发生错误:', error);
      showFeedback(`执行步骤时发生错误: ${error.message}`);
    }
  }

  /**
   * 更新剧情执行状态到世界书（新数据格式）
   */
  async function updateStoryExecutionStatus(currentStory) {
    // 只在生产环境中执行
    if (isDev) {
      console.log('🔧 开发环境：跳过剧情状态更新操作');
      return;
    }

    try {
      console.log('📝 生产环境：开始更新剧情执行状态:', currentStory.id);

      // 获取世界书名称
      const worldbookName = await getWorldbookName();
      if (!worldbookName) {
        throw new Error('无法获取世界书名称');
      }

      // 使用updateWorldbookWith更新世界书
      await updateWorldbookWith(worldbookName, worldbook => {
        return worldbook.map(entry => {
          if (entry.name.includes('剧情元数据-By萧谴剧情模拟器')) {
            let currentData;
            try {
              currentData = JSON.parse(entry.content);
            } catch (error) {
              console.error('解析世界书数据失败:', error);
              throw new Error('世界书数据格式错误');
            }

            // 更新plotList中对应剧情的步骤执行状态
            const updatedPlotList = currentData.plotList.map(plot => {
              if (plot.uniqueID === currentStory.id) {
                // 同步当前剧情的步骤执行状态（使用 == 允许字符串和数字比较）
                const updatedSteps = plot.steps.map(step => {
                  const localStep = currentStory.steps.find(s => s.stepId == step.stepId);
                  return localStep ? { ...step, isExecute: localStep.isExecute } : step;
                });

                return {
                  ...plot,
                  steps: updatedSteps,
                };
              }
              return plot;
            });

            const updatedData = {
              ...currentData,
              plotList: updatedPlotList,
              currentPlot: {
                uniqueID: currentPlot,
                stepId: currentStepId,
              },
            };

            console.log('📝 生产环境：更新剧情状态完成');

            return {
              ...entry,
              content: JSON.stringify(updatedData, null, 2),
            };
          }
          return entry;
        });
      });

      console.log('✅ 生产环境：剧情执行状态保存完成');
    } catch (error) {
      console.error('❌ 生产环境：更新剧情状态失败:', error);
      // 不抛出错误，避免影响主流程
    }
  }

  /**
   * 获取世界书名称
   */
  async function getWorldbookName() {
    try {
      const charWorldbooks = getCharWorldbookNames('current');
      return charWorldbooks?.primary || null;
    } catch (error) {
      console.error('获取世界书名称失败:', error);
      return null;
    }
  }

  /**
   * 保存当前剧情状态到世界书
   */
  async function saveCurrentPlotToWorldbook() {
    // 只在生产环境中执行
    if (isDev) {
      console.log('🔧 开发环境：跳过世界书保存操作');
      return;
    }

    try {
      console.log('💾 生产环境：开始保存currentPlot到世界书');
      console.log('📊 当前状态：', { currentPlot, currentStepId });

      // 获取世界书名称
      const worldbookName = await getWorldbookName();
      if (!worldbookName) {
        throw new Error('无法获取世界书名称');
      }

      // 使用updateWorldbookWith更新世界书
      await updateWorldbookWith(worldbookName, worldbook => {
        return worldbook.map(entry => {
          if (entry.name.includes('剧情元数据-By萧谴剧情模拟器')) {
            let currentData;
            try {
              currentData = JSON.parse(entry.content);
            } catch (error) {
              console.error('解析世界书数据失败:', error);
              throw new Error('世界书数据格式错误');
            }

            // 更新currentPlot对象
            const updatedData = {
              ...currentData,
              currentPlot: {
                uniqueID: currentPlot,
                stepId: currentStepId,
              },
            };

            console.log('📝 生产环境：更新currentPlot为:', updatedData.currentPlot);

            return {
              ...entry,
              content: JSON.stringify(updatedData, null, 2),
            };
          }
          return entry;
        });
      });

      console.log('✅ 生产环境：currentPlot保存完成');
    } catch (error) {
      console.error('❌ 生产环境：保存currentPlot失败:', error);
      // 不抛出错误，避免影响主流程
    }
  }

  /**
   * 构建要发送的步骤对象
   */
  function buildStepObject(story, step) {
    return {
      location: story.location,
      characters: step.characters,
      event: step.event,
      development: step.development,
    };
  }

  /**
   * 将步骤对象格式化为要发送的文本
   */
  function formatStepObjectAsText(stepObject) {
    // 直接将 JSON 对象格式化为文本发送
    return 'step_data = ' + JSON.stringify(stepObject, null, 2);
  }

  /**
   * 显示操作反馈
   */
  function showFeedback(message) {
    const $feedback = $('#feedbackMessage');
    $feedback.text(message).addClass('show');

    setTimeout(() => {
      $feedback.removeClass('show');
    }, 2000);
  }

  /**
   * 与 SillyTavern 通信的快速回复函数（直接执行）
   */
  const triggerQuickReply = text => {
    // 调用前text去除前后空格
    const trimmedText = text ? text.trim() : '';

    // 检查文本有效性，避免发送空内容
    if (!trimmedText || ['…', '...'].includes(trimmedText) || trimmedText.length === 0) return;

    // 检查SillyTavern环境并发送命令
    if (typeof triggerSlash === 'function') {
      triggerSlash(`/send ${trimmedText}|/trigger`);
    } else {
      console.log('SillyTavern environment not detected. Would send:', trimmedText);
    }
  };

  /**
   * 复制文本到酒馆对话框（不自动执行）
   * @param {string} text - 要复制的文本内容
   */
  const copyToTavernTextarea = text => {
    try {
      // 调用前text去除前后空格
      const trimmedText = text ? text.trim() : '';

      // 检查文本有效性，避免复制空内容
      if (!trimmedText || ['…', '...'].includes(trimmedText) || trimmedText.length === 0) {
        console.warn('❌ 文本内容为空，无法复制');
        showFeedback('文本内容为空，无法复制');
        return false;
      }

      // 使用jQuery获取父页面的元素（当前页面是iframe）
      const $parentTextarea = window.parent.$('#send_textarea');

      if ($parentTextarea.length === 0) {
        console.error('❌ 无法找到父页面的 #send_textarea 元素');
        showFeedback('无法找到酒馆对话框，请确认页面已正确加载');
        return false;
      }

      // 获取当前输入框的值
      const currentValue = $parentTextarea.val() || '';

      // 将文本追加到输入框（不是替换）
      const newValue = currentValue ? `${currentValue}\n${trimmedText}` : trimmedText;
      $parentTextarea.val(newValue);

      console.log('✅ 文本已复制到酒馆对话框');
      console.log('📝 复制的内容:', trimmedText);

      return true;
    } catch (error) {
      console.error('❌ 复制到酒馆对话框时出错:', error);
      showFeedback(`复制失败: ${error.message}`);
      return false;
    }
  };

  /**
   * 获取当前剧情信息（供外部调用）
   */
  window.getCurrentStory = function () {
    return stories[currentStoryIndex];
  };

  /**
   * 跳转到指定剧情（供外部调用）
   */
  window.goToStory = function (index) {
    if (index >= 0 && index < stories.length) {
      currentStoryIndex = index;
      updateDisplay();
      return true;
    }
    return false;
  };

  /**
   * 设置剧情数据（供外部调用）
   */
  window.setStoryData = function (newStories) {
    if (Array.isArray(newStories) && newStories.length > 0) {
      stories = newStories;
      currentStoryIndex = 0;
      updateDisplay();
      return true;
    }
    return false;
  };

  /**
   * 获取当前步骤信息（供外部调用）
   */
  window.getCurrentStep = function () {
    const story = stories[currentStoryIndex];
    if (!story) return null;

    return {
      story: story.title,
      stepId: story.currentStepId,
      step: getCurrentStepInfo(story, story.currentStepId),
      totalSteps: story.steps?.length || 0,
    };
  };

  /**
   * 暴露 triggerQuickReply 函数到全局作用域（供外部调用）
   */
  window.triggerQuickReply = triggerQuickReply;

  // 初始化插件
  initStoryAssistant();

  console.log('剧情小助手初始化完成');
});


