      // 额外通知高度变化（确保iframe正确调整）
      setTimeout(() => {
        if (typeof window.notifyParentHeightChange === 'function') {
          window.notifyParentHeightChange();
        }
      }, 100);

      // 再次通知（防止初次计算不准确）
      setTimeout(() => {
        if (typeof window.notifyParentHeightChange === 'function') {
          window.notifyParentHeightChange();
        }
      }, 400);
    } catch (error) {
      console.error('showStoryDetail 错误:', error);
      showFeedback(`显示剧情详情时出错: ${error.message}`);
    }
